#'
#' @export
pydecisioncalculator <- function(
    data,
    tp = 90,
    fp = 30,
    fn = 20,
    tn = 80,
    ciWidth = 95,
    usePrevalence = FALSE,
    prevalence = 0.3,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pydecisioncalculator requires jmvcore to be installed (restart may be required)")

    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame())


    options <- pydecisioncalculatorOptions$new(
        tp = tp,
        fp = fp,
        fn = fn,
        tn = tn,
        ciWidth = ciWidth,
        usePrevalence = usePrevalence,
        prevalence = prevalence,
        showConsole = showConsole)

    analysis <- pydecisioncalculatorClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

